let myEligiblePlans = [];
let myEnrollments = [];
let myActivePeriod = null;
let myApprovedWindowEvent = null;
let myLifeEvents = [];
let myDependents = [];
let myClaims = [];
const myBenefitsPlansList = createListState({ sortKey: 'plan_name' });
const myLifeEventsList = createListState({ sortKey: 'event_date', sortDir: 'desc' });
const myDependentsList = createListState({ sortKey: 'full_name' });
const myClaimsList = createListState({ sortKey: 'claim_date', sortDir: 'desc' });

async function loadMyBenefitsPage() {
  const [plansRes, enrollRes, periodRes, eventsRes, depsRes, claimsRes] = await Promise.all([
    api('/api/benefits/eligible-plans/mine'),
    api('/api/benefits/enrollments/mine'),
    api('/api/benefits/enrollment-periods/active'),
    api('/api/benefits/life-events/mine'),
    api('/api/benefits/dependents/mine'),
    api('/api/benefits/claims/mine'),
  ]);

  myEligiblePlans = (plansRes && plansRes.ok) ? await plansRes.json() : [];
  myEnrollments = (enrollRes && enrollRes.ok) ? await enrollRes.json() : [];
  myActivePeriod = (periodRes && periodRes.ok) ? await periodRes.json() : null;
  myLifeEvents = (eventsRes && eventsRes.ok) ? await eventsRes.json() : [];
  myDependents = (depsRes && depsRes.ok) ? await depsRes.json() : [];
  myClaims = (claimsRes && claimsRes.ok) ? await claimsRes.json() : [];

  const today = new Date().toISOString().slice(0, 10);
  myApprovedWindowEvent = myLifeEvents.find(e => e.status === 'Approved' && e.window_end_date && e.window_end_date >= today) || null;

  myBenefitsPlansList.resetPage();
  myLifeEventsList.resetPage();
  myDependentsList.resetPage();
  myClaimsList.resetPage();

  renderMyBenefitsBanner();
  renderMyBenefitsPlansTable();
  renderMyLifeEventsTable();
  renderMyClaimsTable();
  renderMyDependentsTable();
}

function setMyBenefitsPlansSort(key) { myBenefitsPlansList.setSort(key); renderMyBenefitsPlansTable(); }
function setMyBenefitsPlansPageSize(size) { myBenefitsPlansList.setPageSize(size); renderMyBenefitsPlansTable(); }
function myBenefitsPlansPagePrev() { myBenefitsPlansList.prevPage(); renderMyBenefitsPlansTable(); }
function myBenefitsPlansPageNext() { myBenefitsPlansList.nextPage(myEligiblePlans.length); renderMyBenefitsPlansTable(); }

function setMyLifeEventsSort(key) { myLifeEventsList.setSort(key); renderMyLifeEventsTable(); }
function setMyLifeEventsPageSize(size) { myLifeEventsList.setPageSize(size); renderMyLifeEventsTable(); }
function myLifeEventsPagePrev() { myLifeEventsList.prevPage(); renderMyLifeEventsTable(); }
function myLifeEventsPageNext() { myLifeEventsList.nextPage(myLifeEvents.length); renderMyLifeEventsTable(); }

function setMyClaimsSort(key) { myClaimsList.setSort(key); renderMyClaimsTable(); }
function setMyClaimsPageSize(size) { myClaimsList.setPageSize(size); renderMyClaimsTable(); }
function myClaimsPagePrev() { myClaimsList.prevPage(); renderMyClaimsTable(); }
function myClaimsPageNext() { myClaimsList.nextPage(myClaims.length); renderMyClaimsTable(); }

function setMyDependentsSort(key) { myDependentsList.setSort(key); renderMyDependentsTable(); }
function setMyDependentsPageSize(size) { myDependentsList.setPageSize(size); renderMyDependentsTable(); }
function myDependentsPagePrev() { myDependentsList.prevPage(); renderMyDependentsTable(); }
function myDependentsPageNext() { myDependentsList.nextPage(myDependents.length); renderMyDependentsTable(); }

function renderMyDependentsTable() {
  renderDependentsTable(document.getElementById('myDependentsTableBody'), document.getElementById('myDependentsEmptyState'), myDependents, true, undefined, undefined, myDependentsList, 'myDependents');
}

function renderMyBenefitsBanner() {
  const banner = document.getElementById('myBenefitsWindowBanner');
  if (myActivePeriod) {
    banner.className = 'mb-4 rounded-xl border px-4 py-3 text-sm bg-emerald-50 border-emerald-200 text-emerald-800';
    banner.textContent = `Open enrollment is active: "${myActivePeriod.period_name}" through ${fmtDate(myActivePeriod.end_date)}. You can enroll or change your elections now.`;
    banner.classList.remove('hidden');
  } else if (myApprovedWindowEvent) {
    banner.className = 'mb-4 rounded-xl border px-4 py-3 text-sm bg-blue-50 border-blue-200 text-blue-800';
    banner.textContent = `You have a life-event enrollment window open until ${fmtDate(myApprovedWindowEvent.window_end_date)} (${myApprovedWindowEvent.event_type}).`;
    banner.classList.remove('hidden');
  } else {
    banner.className = 'mb-4 rounded-xl border px-4 py-3 text-sm bg-slate-50 border-slate-200 text-slate-600';
    banner.textContent = 'No open enrollment period is currently active. You can still submit a life event if you have a qualifying change.';
    banner.classList.remove('hidden');
  }
}

function renderMyBenefitsPlansTable() {
  const tbody = document.getElementById('myBenefitsPlansTableBody');
  if (!tbody) return;
  document.getElementById('myBenefitsPlansEmptyState')?.classList.toggle('hidden', myEligiblePlans.length > 0);
  myBenefitsPlansList.updateSortArrows('.my-benefits-plans-sort-arrow');
  const canElect = !!(myActivePeriod || myApprovedWindowEvent);

  const pagination = document.getElementById('myBenefitsPlansPagination');
  if (!myEligiblePlans.length) { pagination?.classList.add('hidden'); tbody.innerHTML = ''; return; }
  pagination?.classList.remove('hidden');
  const pageSizeEl = document.getElementById('myBenefitsPlansPageSize');
  if (pageSizeEl) pageSizeEl.value = String(myBenefitsPlansList.pageSize);

  const { pageItems, start, total } = myBenefitsPlansList.view(myEligiblePlans);
  const pageInfoEl = document.getElementById('myBenefitsPlansPageInfo');
  if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + myBenefitsPlansList.pageSize, total)} of ${total}`;

  const fmtCost = (v, type) => {
    if (v == null) return '—';
    if (type === 'Percent of Salary') return `${Number(v)}%`;
    return fmtCurrency(v);
  };

  tbody.innerHTML = pageItems.map(p => {
    const enrollment = myEnrollments.find(e => e.benefit_plan_id === p.id);
    const electionBadge = !enrollment ? 'status-neutral'
      : enrollment.status === 'Enrolled' ? 'status-positive' : 'status-neutral';
    const electionLabel = enrollment ? enrollment.status : 'Not elected';
    return `
      <tr>
        <td class="px-4 py-3 font-medium">${esc(p.plan_name)}</td>
        <td class="px-4 py-3"><span class="badge status-special">${esc(p.plan_category)}</span></td>
        <td class="px-4 py-3 text-right">${fmtCost(p.employee_cost, p.contribution_type)}</td>
        <td class="px-4 py-3"><span class="badge ${electionBadge}">${esc(electionLabel)}</span></td>
        <td class="px-4 py-3 text-right">
          ${canElect ? `
            <button onclick="electMyBenefit(${p.id}, 'Enrolled')" class="text-xs text-emerald-700 hover:underline mr-3">Enroll</button>
            <button onclick="electMyBenefit(${p.id}, 'Waived')" class="text-xs text-slate-600 hover:underline">Waive</button>
          ` : '<span class="text-xs text-slate-400">No open window</span>'}
        </td>
      </tr>
    `;
  }).join('');
}

function renderMyLifeEventsTable() {
  const tbody = document.getElementById('myLifeEventsTableBody');
  if (!tbody) return;
  document.getElementById('myLifeEventsEmptyState')?.classList.toggle('hidden', myLifeEvents.length > 0);
  myLifeEventsList.updateSortArrows('.my-life-events-sort-arrow');

  const pagination = document.getElementById('myLifeEventsPagination');
  if (!myLifeEvents.length) { pagination?.classList.add('hidden'); tbody.innerHTML = ''; return; }
  pagination?.classList.remove('hidden');
  const pageSizeEl = document.getElementById('myLifeEventsPageSize');
  if (pageSizeEl) pageSizeEl.value = String(myLifeEventsList.pageSize);

  const { pageItems, start, total } = myLifeEventsList.view(myLifeEvents);
  const pageInfoEl = document.getElementById('myLifeEventsPageInfo');
  if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + myLifeEventsList.pageSize, total)} of ${total}`;

  const statusBadge = status => {
    if (status === 'Approved') return 'status-info';
    if (status === 'Rejected') return 'status-negative';
    return 'status-pending';
  };
  tbody.innerHTML = pageItems.map(ev => `
    <tr>
      <td class="px-4 py-3">${esc(ev.event_type)}</td>
      <td class="px-4 py-3">${fmtDate(ev.event_date)}</td>
      <td class="px-4 py-3"><span class="badge ${statusBadge(ev.status)}">${esc(ev.status)}</span></td>
    </tr>
  `).join('');
}

async function electMyBenefit(planId, status) {
  const body = { benefit_plan_id: planId, status };
  if (!myActivePeriod && myApprovedWindowEvent) body.life_event_id = myApprovedWindowEvent.id;
  const res = await api('/api/benefits/enrollments/mine', { method: 'POST', body: JSON.stringify(body) });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  loadMyBenefitsPage();
}

function openLifeEventForm() {
  document.getElementById('lifeEventForm').reset();
  document.getElementById('lifeEventModal').classList.remove('hidden');
}

function closeLifeEventModal() { closeModal('lifeEventModal'); }

async function submitLifeEventForm(e) {
  e.preventDefault();
  const g = id => document.getElementById(id).value;
  const body = {
    event_type: g('leType'),
    event_date: g('leDate'),
    notes: g('leNotes').trim() || null,
  };
  const res = await api('/api/benefits/life-events/mine', { method: 'POST', body: JSON.stringify(body) });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  closeLifeEventModal();
  loadMyBenefitsPage();
}

// ============================================================================
// DEPENDENTS / BENEFICIARIES (shared HR + self-service)
// ============================================================================

let dependentFormContext = 'self'; // 'self' or 'hr'
let currentDependentsEmployeeId = null;

function renderDependentsTable(tbody, emptyState, deps, showActions, context, employeeId, listState, idPrefix) {
  if (!tbody) return;
  emptyState?.classList.toggle('hidden', deps.length > 0);

  if (listState && idPrefix) {
    listState.updateSortArrows(`.${idPrefix}-sort-arrow`);
    const pagination = document.getElementById(`${idPrefix}Pagination`);
    if (!deps.length) { pagination?.classList.add('hidden'); tbody.innerHTML = ''; return; }
    pagination?.classList.remove('hidden');
    const pageSizeEl = document.getElementById(`${idPrefix}PageSize`);
    if (pageSizeEl) pageSizeEl.value = String(listState.pageSize);
    const { pageItems, start, total } = listState.view(deps);
    const pageInfoEl = document.getElementById(`${idPrefix}PageInfo`);
    if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + listState.pageSize, total)} of ${total}`;
    deps = pageItems;
  }

  tbody.innerHTML = deps.map(d => `
    <tr>
      <td class="px-4 py-3">
        <p class="font-medium">${esc(d.full_name)}</p>
        ${d.national_id ? `<p class="text-xs text-slate-500">${esc(d.national_id)}</p>` : ''}
      </td>
      <td class="px-4 py-3">${esc(d.relationship)}</td>
      <td class="px-4 py-3">${fmtDate(d.date_of_birth)}</td>
      <td class="px-4 py-3 text-center">
        ${d.is_beneficiary ? `<span class="badge bg-blue-100 text-blue-700">${d.beneficiary_percentage != null ? d.beneficiary_percentage + '%' : 'Yes'}</span>` : '<span class="text-xs text-slate-400">—</span>'}
      </td>
      ${showActions ? `<td class="px-4 py-3 text-right"><button onclick='openDependentForm(${JSON.stringify(d)}, ${JSON.stringify(context)}, ${JSON.stringify(employeeId)})' class="text-xs text-blue-700 hover:underline">Edit</button></td>` : ''}
    </tr>
  `).join('');
}

// Edit Employee > Dependents tab (HR-facing, per employee)
let empDependents = [];
const empDependentsList = createListState({ sortKey: 'full_name' });

async function loadEmpDependentsTab() {
  const res = await api(`/api/benefits/employees/${currentEmpId}/dependents`);
  empDependents = (res && res.ok) ? await res.json() : [];
  empDependentsList.resetPage();
  renderEmpDependentsTable();
}

function setEmpDependentsSort(key) { empDependentsList.setSort(key); renderEmpDependentsTable(); }
function setEmpDependentsPageSize(size) { empDependentsList.setPageSize(size); renderEmpDependentsTable(); }
function empDependentsPagePrev() { empDependentsList.prevPage(); renderEmpDependentsTable(); }
function empDependentsPageNext() { empDependentsList.nextPage(empDependents.length); renderEmpDependentsTable(); }

function renderEmpDependentsTable() {
  renderDependentsTable(document.getElementById('empDependentsTableBody'), document.getElementById('empDependentsEmptyState'), empDependents, true, 'hr', currentEmpId, empDependentsList, 'empDependents');
}

function toggleBeneficiaryPercentRow() {
  document.getElementById('depBeneficiaryPercentRow').classList.toggle('hidden', !document.getElementById('depIsBeneficiary').checked);
}

function openDependentForm(existing, context, employeeId) {
  dependentFormContext = context || 'self';
  currentDependentsEmployeeId = employeeId || null;
  document.getElementById('dependentForm').reset();
  document.getElementById('depBeneficiaryPercentRow').classList.add('hidden');
  document.getElementById('depId').value = '';

  if (existing && existing.id) {
    document.getElementById('dependentModalTitle').textContent = 'Edit Dependent';
    document.getElementById('depId').value = existing.id;
    document.getElementById('depName').value = existing.full_name;
    document.getElementById('depRelationship').value = existing.relationship;
    document.getElementById('depDob').value = existing.date_of_birth || '';
    document.getElementById('depNationalId').value = existing.national_id || '';
    document.getElementById('depIsBeneficiary').checked = !!existing.is_beneficiary;
    document.getElementById('depBeneficiaryPercent').value = existing.beneficiary_percentage ?? '';
    document.getElementById('depNotes').value = existing.notes || '';
    if (existing.is_beneficiary) document.getElementById('depBeneficiaryPercentRow').classList.remove('hidden');
  } else {
    document.getElementById('dependentModalTitle').textContent = 'Add Dependent';
  }

  document.getElementById('dependentModal').classList.remove('hidden');
}

function closeDependentModal() { closeModal('dependentModal'); }

async function submitDependentForm(e) {
  e.preventDefault();
  const g = id => document.getElementById(id).value;
  const depId = g('depId');
  const body = {
    full_name: g('depName').trim(),
    relationship: g('depRelationship'),
    date_of_birth: g('depDob') || null,
    national_id: g('depNationalId').trim() || null,
    is_beneficiary: document.getElementById('depIsBeneficiary').checked,
    beneficiary_percentage: g('depBeneficiaryPercent') ? parseFloat(g('depBeneficiaryPercent')) : null,
    notes: g('depNotes').trim() || null,
  };

  let res;
  if (depId) {
    res = await api(`/api/benefits/dependents/${depId}`, { method: 'PUT', body: JSON.stringify(body) });
  } else if (dependentFormContext === 'hr') {
    res = await api(`/api/benefits/employees/${currentDependentsEmployeeId}/dependents`, { method: 'POST', body: JSON.stringify(body) });
  } else {
    res = await api('/api/benefits/dependents/mine', { method: 'POST', body: JSON.stringify(body) });
  }

  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  closeDependentModal();

  if (dependentFormContext === 'hr') {
    loadEmpDependentsTab();
  } else {
    loadMyBenefitsPage();
  }
}

// ============================================================================
// CLAIMS TRACKING
// ============================================================================

function claimStatusBadge(status) {
  if (status === 'Approved') return 'status-info';
  if (status === 'Paid') return 'status-positive';
  if (status === 'Rejected') return 'status-negative';
  return 'status-pending';
}

let currentClaims = [];
const claimsList = createListState({ sortKey: 'claim_date', sortDir: 'desc' });

async function loadClaims() {
  const res = await api('/api/benefits/claims');
  if (!res || !res.ok) return;
  currentClaims = await res.json();
  claimsList.resetPage();
  renderClaimsTable();
}

function setClaimsSort(key) { claimsList.setSort(key); renderClaimsTable(); }
function setClaimsPageSize(size) { claimsList.setPageSize(size); renderClaimsTable(); }
function claimsPagePrev() { claimsList.prevPage(); renderClaimsTable(); }
function claimsPageNext() { claimsList.nextPage(currentClaims.length); renderClaimsTable(); }

function renderClaimsTable() {
  const tbody = document.getElementById('claimsTableBody');
  if (!tbody) return;
  document.getElementById('claimsEmptyState')?.classList.toggle('hidden', currentClaims.length > 0);
  claimsList.updateSortArrows('.claims-sort-arrow');

  const pagination = document.getElementById('claimsPagination');
  if (!currentClaims.length) { pagination?.classList.add('hidden'); tbody.innerHTML = ''; return; }
  pagination?.classList.remove('hidden');
  const pageSizeEl = document.getElementById('claimsPageSize');
  if (pageSizeEl) pageSizeEl.value = String(claimsList.pageSize);

  const { pageItems, start, total } = claimsList.view(currentClaims);
  const pageInfoEl = document.getElementById('claimsPageInfo');
  if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + claimsList.pageSize, total)} of ${total}`;

  tbody.innerHTML = pageItems.map(c => `
    <tr>
      <td class="px-4 py-3">
        <p class="font-medium">${esc(c.employee_name ? displayName(c.employee_name, c.employee_preferred_name) : c.employee_id)}</p>
        <p class="text-xs text-slate-500">${esc(c.employee_id)}</p>
      </td>
      <td class="px-4 py-3">
        <p>${esc(c.plan_name)}</p>
        <p class="text-xs text-slate-500">${esc(c.plan_category)}</p>
      </td>
      <td class="px-4 py-3">${fmtDate(c.claim_date)}</td>
      <td class="px-4 py-3 text-right">${fmtCurrency(c.amount_claimed)}</td>
      <td class="px-4 py-3 text-right">${fmtCurrency(c.amount_approved)}</td>
      <td class="px-4 py-3">
        <span class="badge ${claimStatusBadge(c.status)}">${esc(c.status)}</span>
        ${c.payout_date ? `<p class="text-xs text-slate-400 mt-1">Paid ${fmtDate(c.payout_date)}</p>` : ''}
      </td>
      <td class="px-4 py-3 text-right">
        ${(c.status === 'Submitted' || c.status === 'Under Review') ? (c.is_actionable ? `
          <button onclick="openClaimDecideModal(${c.id})" class="text-xs text-emerald-700 hover:underline mr-3">Approve</button>
          <button onclick="rejectClaim(${c.id})" class="text-xs text-red-700 hover:underline">Reject</button>
        ` : `<span class="text-xs text-slate-400">Pending: ${esc(c.pending_with || '—')}</span>`) : c.status === 'Approved' ? `
          <button onclick="markClaimPaid(${c.id})" class="text-xs text-blue-700 hover:underline">Mark Paid</button>
        ` : '<span class="text-xs text-slate-400">—</span>'}
      </td>
    </tr>
  `).join('');
}

async function rejectClaim(claimId) {
  const res = await api(`/api/benefits/claims/${claimId}/decide`, { method: 'PUT', body: JSON.stringify({ status: 'Rejected' }) });
  if (!res || !res.ok) { alert('Error rejecting claim'); return; }
  loadClaims();
}

let currentDecideClaimId = null;

function openClaimDecideModal(claimId) {
  const claim = currentClaims.find(c => c.id === claimId);
  if (!claim) return;
  currentDecideClaimId = claimId;
  document.getElementById('claimDecideInfo').textContent =
    `${claim.employee_name ? displayName(claim.employee_name, claim.employee_preferred_name) : claim.employee_id} claimed ${fmtCurrency(claim.amount_claimed)} under '${claim.plan_name}' (${fmtDate(claim.claim_date)}). Reimbursement Cap plans are capped by the employee's remaining annual balance — an over-cap amount will be rejected by the server with the remaining balance shown.`;
  document.getElementById('claimDecideAmount').value = claim.amount_claimed;
  document.getElementById('claimDecideModal').classList.remove('hidden');
}

function closeClaimDecideModal() { closeModal('claimDecideModal', () => currentDecideClaimId = null); }

async function submitClaimDecideForm(e) {
  e.preventDefault();
  const amount_approved = parseFloat(document.getElementById('claimDecideAmount').value);
  const res = await api(`/api/benefits/claims/${currentDecideClaimId}/decide`, {
    method: 'PUT',
    body: JSON.stringify({ status: 'Approved', amount_approved }),
  });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  closeClaimDecideModal();
  loadClaims();
}

async function markClaimPaid(claimId) {
  const res = await api(`/api/benefits/claims/${claimId}/pay`, { method: 'PUT' });
  if (!res || !res.ok) { alert('Error marking claim as paid'); return; }
  loadClaims();
}

function renderMyClaimsTable() {
  const tbody = document.getElementById('myClaimsTableBody');
  if (!tbody) return;
  document.getElementById('myClaimsEmptyState')?.classList.toggle('hidden', myClaims.length > 0);
  myClaimsList.updateSortArrows('.my-claims-sort-arrow');

  const pagination = document.getElementById('myClaimsPagination');
  if (!myClaims.length) { pagination?.classList.add('hidden'); tbody.innerHTML = ''; return; }
  pagination?.classList.remove('hidden');
  const pageSizeEl = document.getElementById('myClaimsPageSize');
  if (pageSizeEl) pageSizeEl.value = String(myClaimsList.pageSize);

  const { pageItems, start, total } = myClaimsList.view(myClaims);
  const pageInfoEl = document.getElementById('myClaimsPageInfo');
  if (pageInfoEl) pageInfoEl.textContent = `${start + 1}-${Math.min(start + myClaimsList.pageSize, total)} of ${total}`;

  tbody.innerHTML = pageItems.map(c => `
    <tr>
      <td class="px-4 py-3">${esc(c.plan_name)}</td>
      <td class="px-4 py-3">${fmtDate(c.claim_date)}</td>
      <td class="px-4 py-3 text-right">${fmtCurrency(c.amount_claimed)}</td>
      <td class="px-4 py-3 text-right">${fmtCurrency(c.amount_approved)}</td>
      <td class="px-4 py-3"><span class="badge ${claimStatusBadge(c.status)}">${esc(c.status)}</span></td>
    </tr>
  `).join('');
}

async function openClaimForm() {
  document.getElementById('claimForm').reset();
  const select = document.getElementById('claimPlan');
  select.innerHTML = myEligiblePlans.map(p => `<option value="${p.id}">${esc(p.plan_name)} (${esc(p.plan_category)})</option>`).join('');
  await populateClaimProjectField();
  document.getElementById('claimModal').classList.remove('hidden');
}

async function populateClaimProjectField() {
  const wrap = document.getElementById('claimProjectWrap');
  const sel = document.getElementById('claimProjectId');
  wrap.classList.add('hidden');
  sel.innerHTML = '';
  const needed = await moduleHasProjectManagerStep('claims');
  if (!needed) return;
  const res = await api('/api/projects/mine');
  const myProjects = res?.ok ? await res.json() : [];
  if (!myProjects.length) return;  // no project to pick — step auto-skips
  sel.innerHTML = myProjects.map(p => `<option value="${p.id}">${esc(p.name)}</option>`).join('');
  wrap.classList.remove('hidden');
}

function closeClaimModal() { closeModal('claimModal'); }

async function submitClaimForm(e) {
  e.preventDefault();
  const g = id => document.getElementById(id).value;
  const projectWrap = document.getElementById('claimProjectWrap');
  const body = {
    benefit_plan_id: parseInt(g('claimPlan')),
    claim_date: g('claimDate'),
    amount_claimed: parseFloat(g('claimAmount')),
    description: g('claimDesc').trim() || null,
    project_id: !projectWrap.classList.contains('hidden') && g('claimProjectId') ? parseInt(g('claimProjectId')) : null,
  };
  const res = await api('/api/benefits/claims/mine', { method: 'POST', body: JSON.stringify(body) });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  closeClaimModal();
  loadMyBenefitsPage();
}

// ============================================================================
// COMPLIANCE & REPORTING
// ============================================================================

async function loadComplianceReport() {
  const res = await api('/api/benefits/reports/summary');
  if (!res || !res.ok) return;
  renderComplianceReport(await res.json());
}

function renderComplianceReport(r) {
  document.getElementById('crActivePlans').textContent = r.total_active_plans;
  document.getElementById('crEnrolledEmployees').textContent = r.total_enrolled_employees;
  document.getElementById('crEmployerCost').textContent = fmtCurrency(r.total_monthly_employer_cost);
  document.getElementById('crClaimsPaid').textContent = fmtCurrency(r.total_claims_paid_ytd);

  const flagsEl = document.getElementById('crComplianceFlags');
  if (r.compliance_flags.length === 0) {
    flagsEl.innerHTML = '<p class="text-sm bg-emerald-50 border border-emerald-200 text-emerald-800 rounded-xl px-4 py-3">No compliance documentation gaps detected.</p>';
  } else {
    flagsEl.innerHTML = `
      <div class="bg-amber-50 border border-amber-200 rounded-xl px-4 py-3">
        <p class="text-sm font-semibold text-amber-800 mb-2">Compliance flags (${r.compliance_flags.length})</p>
        <ul class="text-sm text-amber-800 list-disc list-inside space-y-1">
          ${r.compliance_flags.map(f => `<li>${esc(f)}</li>`).join('')}
        </ul>
      </div>
    `;
  }

  const tbody = document.getElementById('crPlansTableBody');
  document.getElementById('crPlansEmptyState')?.classList.toggle('hidden', r.plans.length > 0);
  tbody.innerHTML = r.plans.map(p => `
    <tr>
      <td class="px-4 py-3">
        <p class="font-medium">${esc(p.plan_name)}</p>
        <p class="text-xs text-slate-500">${esc(p.plan_category)}${p.carrier_name ? ' · ' + esc(p.carrier_name) : ''}</p>
      </td>
      <td class="px-4 py-3 text-right">${p.enrolled_count}</td>
      <td class="px-4 py-3 text-right">${p.waived_count}</td>
      <td class="px-4 py-3 text-right">${p.participation_rate != null ? p.participation_rate + '%' : '—'}</td>
      <td class="px-4 py-3 text-right">${p.contribution_type === 'Fixed Premium' ? fmtCurrency(p.monthly_employer_cost_total) : '—'}</td>
      <td class="px-4 py-3 text-right">${fmtCurrency(p.claims_paid_total)}</td>
    </tr>
  `).join('');
}

;
// ---- attendance.js ----
// Attendance: Clock In/Out, HR Review, Shifts + Rules + Assignments settings
// ---------------------------------------------------------------------------
let attHistoryCache = [];
let attReviewCache = [];
let attShiftsCache = [];
let attCurrentGeo = null; // {lat, lng} captured once per page load

const ATT_STATUS_COLORS = {
  'Present': 'status-positive',
  'Late': 'status-pending',
  'Absent (Pending Review)': 'status-negative',
  'Excused': 'status-info',
  'Reclassified as Leave': 'status-special',
  'Confirmed Absent': 'status-neutral',
};

function attStatusBadge(status) {
  const cls = statusColor(ATT_STATUS_COLORS, status);
  return `<span class="px-2 py-0.5 rounded-sm text-xs font-medium ${cls}">${esc(status)}</span>`;
}

function attCaptureGeo() {
  return new Promise((resolve) => {
    if (!navigator.geolocation) { resolve(null); return; }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => resolve(null),
      { timeout: 5000 }
    );
  });
}

// ---------------------------------------------------------------------------
// Clock In / Out (self-service)
// ---------------------------------------------------------------------------
async function loadAttendanceClockPage() {
  document.getElementById('attClockGeoNote').textContent = 'Requesting location for geofence check…';
  attCurrentGeo = await attCaptureGeo();
  document.getElementById('attClockGeoNote').textContent = attCurrentGeo
    ? 'Location captured.' : 'Location unavailable — clock-in will still work, just without a geofence check.';

  const res = await api('/api/attendance/mine?limit=30');
  if (!res || !res.ok) return;
  attHistoryCache = await res.json();
  renderAttClockStatus();
  renderAttHistory();
}

function renderAttClockStatus() {
  const open = attHistoryCache.find(r => r.clock_in_at && !r.clock_out_at);
  const inBtn = document.getElementById('attClockInBtn');
  const outBtn = document.getElementById('attClockOutBtn');
  const statusEl = document.getElementById('attClockStatus');
  const detailEl = document.getElementById('attClockDetail');

  if (open) {
    statusEl.textContent = 'Clocked In';
    detailEl.textContent = `Since ${fmtDateTime(open.clock_in_at)} (${esc(open.shift_name || 'no shift')})`;
    inBtn.classList.add('hidden');
    outBtn.classList.remove('hidden');
  } else {
    const today = attHistoryCache.find(r => r.work_date === new Date().toISOString().slice(0, 10));
    if (today && today.clock_out_at) {
      statusEl.textContent = 'Clocked Out';
      detailEl.textContent = `Worked ${today.worked_minutes ?? '—'} min today`;
    } else {
      statusEl.textContent = 'Not Clocked In';
      detailEl.textContent = '';
    }
    inBtn.classList.remove('hidden');
    outBtn.classList.add('hidden');
  }
}

function renderAttHistory() {
  const el = document.getElementById('attHistoryList');
  document.getElementById('attHistoryEmpty')?.classList.toggle('hidden', attHistoryCache.length > 0);
  el.innerHTML = attHistoryCache.map(r => `
    <tr class="border-t border-slate-100">
      <td class="px-4 py-2 text-sm">${fmtDate(r.work_date)}</td>
      <td class="px-4 py-2 text-sm text-slate-500">${esc(r.shift_name || '—')}</td>
      <td class="px-4 py-2 text-sm">${r.clock_in_at ? parseUTC(r.clock_in_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '—'}</td>
      <td class="px-4 py-2 text-sm">${r.clock_out_at ? parseUTC(r.clock_out_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '—'}</td>
      <td class="px-4 py-2 text-sm text-right">${r.worked_minutes != null ? r.worked_minutes + ' min' : '—'}</td>
      <td class="px-4 py-2">${attStatusBadge(r.status)}${r.outside_geofence ? ' <span class="text-xs text-amber-600">(outside geofence)</span>' : ''}</td>
    </tr>`).join('');
}

async function attendanceClockIn() {
  const res = await api('/api/attendance/clock-in', {
    method: 'POST',
    body: JSON.stringify({ lat: attCurrentGeo?.lat ?? null, lng: attCurrentGeo?.lng ?? null }),
  });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  loadAttendanceClockPage();
}

async function attendanceClockOut() {
  const res = await api('/api/attendance/clock-out', {
    method: 'POST',
    body: JSON.stringify({ lat: attCurrentGeo?.lat ?? null, lng: attCurrentGeo?.lng ?? null }),
  });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  loadAttendanceClockPage();
}

// ---------------------------------------------------------------------------
// HR Review
// ---------------------------------------------------------------------------
async function loadAttendanceReview() {
  const res = await api('/api/attendance/review');
  if (!res || !res.ok) return;
  attReviewCache = await res.json();
  const el = document.getElementById('attReviewList');
  document.getElementById('attReviewEmpty')?.classList.toggle('hidden', attReviewCache.length > 0);
  el.innerHTML = attReviewCache.map(r => `
    <tr class="border-t border-slate-100">
      <td class="px-4 py-2 text-sm">
        <div class="font-medium">${esc(r.employee_name ? displayName(r.employee_name, r.employee_preferred_name) : r.employee_id)}</div>
        <div class="text-xs text-slate-400">${esc(r.department || '')}</div>
      </td>
      <td class="px-4 py-2 text-sm">${fmtDate(r.work_date)}</td>
      <td class="px-4 py-2">${attStatusBadge(r.status)}</td>
      <td class="px-4 py-2 text-sm text-slate-500">${esc(r.suggested_action || '—')}</td>
      <td class="px-4 py-2 text-right"><button onclick="openAttResolveModal(${r.id})" class="text-xs text-blue-600 hover:underline">Resolve</button></td>
    </tr>`).join('');
}

let currentAttResolveId = null;

async function openAttResolveModal(id) {
  const rec = attReviewCache.find(r => r.id === id);
  if (!rec) return;
  currentAttResolveId = id;
  document.getElementById('attResolveInfo').textContent =
    `${rec.employee_name ? displayName(rec.employee_name, rec.employee_preferred_name) : rec.employee_id} — ${fmtDate(rec.work_date)} — currently ${rec.status}${rec.suggested_action ? ' (suggested: ' + rec.suggested_action + ')' : ''}`;
  document.getElementById('attResolveAction').value = rec.suggested_action === 'Half-Day Leave' ? 'ReclassifyAsLeave' : (rec.status === 'Late' ? 'Excuse' : 'ReclassifyAsLeave');
  document.getElementById('attResolveHalfDay').checked = rec.suggested_action === 'Half-Day Leave';
  document.getElementById('attResolveNotes').value = '';

  const ltRes = await api('/api/leave/types');
  const leaveTypes = ltRes && ltRes.ok ? await ltRes.json() : [];
  document.getElementById('attResolveLeaveType').innerHTML =
    '<option value="">— Select —</option>' + leaveTypes.map(lt => `<option value="${lt.id}">${esc(lt.name)}</option>`).join('');

  toggleAttResolveLeaveFields();
  document.getElementById('attResolveModal').classList.remove('hidden');
}

function closeAttResolveModal() {
  document.getElementById('attResolveModal').classList.add('hidden');
  currentAttResolveId = null;
}

function toggleAttResolveLeaveFields() {
  const isLeave = document.getElementById('attResolveAction').value === 'ReclassifyAsLeave';
  document.getElementById('attResolveLeaveWrap').classList.toggle('hidden', !isLeave);
}

async function submitAttResolveForm(e) {
  e.preventDefault();
  const action = document.getElementById('attResolveAction').value;
  const body = {
    action,
    notes: document.getElementById('attResolveNotes').value || null,
  };
  if (action === 'ReclassifyAsLeave') {
    body.leave_type_id = parseInt(document.getElementById('attResolveLeaveType').value, 10) || null;
    body.half_day = document.getElementById('attResolveHalfDay').checked;
    if (!body.leave_type_id) { alert('Select a leave type'); return; }
  }
  const res = await api(`/api/attendance/records/${currentAttResolveId}/resolve`, { method: 'PUT', body: JSON.stringify(body) });
  if (!res || !res.ok) { alert('Error: ' + (await res.json()).detail); return; }
  closeAttResolveModal();
  loadAttendanceReview();
}

